[hidden] { display: none !important; }
:root {
  color-scheme: light;
  --ink: #202a44;
  --muted: #65718a;
  --paper: #fffdf5;
  --blue: #4868d8;
  --blue-dark: #3049a6;
  --mint: #c8f0d8;
  --coral: #f28b72;
}
* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 24px 16px;
  display: grid;
  place-items: center;
  background-color: var(--mint);
  background-image: linear-gradient(45deg, rgba(32,42,68,.06) 25%, transparent 25%, transparent 75%, rgba(32,42,68,.06) 75%), linear-gradient(45deg, rgba(32,42,68,.06) 25%, transparent 25%, transparent 75%, rgba(32,42,68,.06) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}
.game-card {
  width: min(100%, 480px);
  padding: clamp(24px, 7vw, 40px);
  background: var(--paper);
  border: 3px solid var(--ink);
  border-radius: 10px;
  box-shadow: 8px 8px 0 var(--ink);
}
.header { text-align: center; }
.pixel-mark {
  width: 56px; height: 44px; margin: 0 auto 12px;
  display: grid; place-items: center;
  border: 3px solid var(--ink); background: var(--coral);
  box-shadow: 4px 4px 0 var(--ink);
  font-weight: 900; letter-spacing: 2px;
}
.eyebrow, .hint-label, .progress-row, footer { font-size: .82rem; font-weight: 800; letter-spacing: .1em; }
.eyebrow { margin: 0; color: var(--blue-dark); }
h1 { margin: 4px 0; font-size: clamp(1.8rem, 8vw, 2.5rem); line-height: 1.15; }
.intro { margin: 0 0 28px; color: var(--muted); }
.progress-row { display: flex; justify-content: space-between; gap: 12px; color: var(--muted); }
.word-box {
  margin: 12px 0 24px; padding: 20px 12px;
  text-align: center; border: 2px dashed var(--blue); border-radius: 8px;
  background: #f0f3ff;
}
.hint-label { margin: 0; color: var(--muted); }
.scrambled-word { margin: 8px 0 0; font-size: clamp(2rem, 10vw, 3rem); font-weight: 900; letter-spacing: .18em; }
label { display: block; margin-bottom: 7px; font-weight: 750; }
input {
  width: 100%; min-height: 52px; padding: 10px 14px;
  border: 2px solid var(--ink); border-radius: 6px;
  background: white; color: var(--ink); font: inherit; font-size: 1.15rem;
}
input:focus-visible, button:focus-visible { outline: 4px solid var(--coral); outline-offset: 3px; }
.feedback { min-height: 28px; margin: 9px 0 14px; color: var(--muted); }
.feedback.correct { color: #246b42; font-weight: 750; }
.feedback.wrong { color: #a3392a; font-weight: 750; }
.button-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.button {
  min-height: 50px; padding: 10px 16px; border: 2px solid var(--ink);
  border-radius: 6px; font: inherit; font-weight: 800; cursor: pointer;
  transition: transform .12s ease, box-shadow .12s ease, background-color .12s ease;
}
.button-primary { color: white; background: var(--blue); box-shadow: 3px 3px 0 var(--ink); }
.button-secondary { color: var(--ink); background: var(--mint); box-shadow: 3px 3px 0 var(--ink); }
.button:hover:not(:disabled) { transform: translateY(-2px); }
.button:active:not(:disabled) { transform: translate(2px, 2px); box-shadow: none; }
.button:disabled { opacity: .48; cursor: not-allowed; box-shadow: none; }
.result-panel { padding: 26px 0 6px; text-align: center; }
.result-panel h2 { margin: 4px 0 8px; font-size: 2rem; }
.final-score { margin: 12px 0; font-size: 1.2rem; }
.result-panel .button { margin-top: 14px; width: 100%; }
footer { margin-top: 28px; text-align: center; color: var(--muted); font-size: .7rem; }
@media (max-width: 380px) {
  body { padding: 16px 12px; }
  .game-card { padding: 22px 18px; }
  .button-row { gap: 9px; }
}

const words = ['planet', 'puzzle', 'garden', 'rocket', 'kitten', 'bright'];
const gamePanel = document.querySelector('#game-panel');
const resultPanel = document.querySelector('#result-panel');
const progress = document.querySelector('#progress');
const liveScore = document.querySelector('#live-score strong');
const scrambledWord = document.querySelector('#scrambled-word');
const answer = document.querySelector('#answer');
const feedback = document.querySelector('#feedback');
const checkButton = document.querySelector('#check-button');
const nextButton = document.querySelector('#next-button');
const finalScore = document.querySelector('#final-score');
const resultMessage = document.querySelector('#result-message');
let wordIndex = 0;
let score = 0;
let checked = false;

function scramble(word) {
  const letters = [...word];
  for (let i = letters.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  if (letters.join('') === word) letters.push(letters.shift());
  return letters.join('').toUpperCase();
}

function showWord() {
  progress.textContent = `WORD ${wordIndex + 1} / ${words.length}`;
  liveScore.textContent = score;
  scrambledWord.textContent = scramble(words[wordIndex]);
  answer.value = '';
  answer.disabled = false;
  checkButton.disabled = false;
  nextButton.disabled = true;
  checked = false;
  feedback.textContent = 'Enter your answer, then check it.';
  feedback.className = 'feedback';
  answer.focus();
}

function checkAnswer(event) {
  event.preventDefault();
  if (checked) return;
  checked = true;
  answer.disabled = true;
  checkButton.disabled = true;
  const isCorrect = answer.value.trim().toLowerCase() === words[wordIndex];
  if (isCorrect) {
    score += 1;
    liveScore.textContent = score;
    feedback.textContent = 'Correct! Great work.';
    feedback.className = 'feedback correct';
  } else {
    feedback.textContent = `Not quite — the word was “${words[wordIndex]}”.`;
    feedback.className = 'feedback wrong';
  }
  nextButton.disabled = false;
  nextButton.focus();
}

function advance() {
  if (!checked) return;
  wordIndex += 1;
  if (wordIndex < words.length) {
    showWord();
    return;
  }
  gamePanel.hidden = true;
  resultPanel.hidden = false;
  finalScore.textContent = `${score} / ${words.length}`;
  resultMessage.textContent = score === words.length ? 'A perfect round!' : 'Thanks for playing. Try again for a new score!';
  document.querySelector('#play-again-button').focus();
}

function restart() {
  wordIndex = 0;
  score = 0;
  gamePanel.hidden = false;
  resultPanel.hidden = true;
  showWord();
}

document.querySelector('#answer-form').addEventListener('submit', checkAnswer);
nextButton.addEventListener('click', advance);
document.querySelector('#play-again-button').addEventListener('click', restart);
showWord();
